+export function parseCsvRecords(text: string): string[][] {
+  const records: string[][] = [];
+  let record: string[] = [];
+  let field = '';
+  let inQuotes = false;
+  let sawAny = false;
+
+  const endRecord = (): void => {
+    record.push(field);
+    // skip blank lines
+    if (!(record.length === 1 && record[0].trim() === '')) records.push(record);
+    record = [];
+    field = '';
+    sawAny = false;
+  };
+
+  for (let i = 0; i < text.length; i++) {
+    const ch = text[i];
+    sawAny = true;
+    if (inQuotes) {
+      if (ch === '"') {
+        if (text[i + 1] === '"') {
+          field += '"';
+          i++;
+        } else {
+          inQuotes = false;
+        }
+      } else {
+        field += ch;
+      }
+    } else if (ch === '"') {
+      inQuotes = true;
+    } else if (ch === ',') {
+      record.push(field);
+      field = '';
+    } else if (ch === '\n' || ch === '\r') {
+      if (ch === '\r' && text[i + 1] === '\n') i++;
+      endRecord();
+    } else {
+      field += ch;
+    }
+  }
+  if (sawAny) endRecord();
+  return records;
+}
+
+/** Same row mapping as the legacy parser, but with proper quote handling. */
+export function parseImportCsv(text: string): LegacyRow[] {
+  const records = parseCsvRecords(text);
+  if (records.length === 0) return [];
+
+  const header = records[0].map((h) => h.trim().toLowerCase());
+  return records.slice(1).map((cells) => {
+    const get = (name: string): string => (cells[header.indexOf(name)] ?? '').trim();
+    const phone = get('phone');
+    return {
+      tracking_number: get('tracking'),
+      carrier: mapLegacyCarrier(get('carrier')),
+      service_level: get('service') || 'standard',
+      recipient: {
+        name: get('name'),
+        street: get('street'),
+        zip: get('zip'),
+        city: get('city'),
+        country: get('country') || 'AT',
+        ...(phone ? { phone } : {}),
+      },
+    };
+  });
+}
